// ---- lib/jsonld.js
function extractJsonLd(html) {
  const out = [];
  const re = /<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  let m;
  while ((m = re.exec(html || ''))) {
    try {
      const v = JSON.parse(m[1].trim());
      for (const x of Array.isArray(v) ? v : (v['@graph'] || [v])) out.push(x);
    } catch (e) { /* bloc invalide ignoré */ }
  }
  return out;
}

function findProduct(objs) {
  return (objs || []).find(o => [].concat(o && o['@type']).includes('Product')) || null;
}

function ratingOf(product) {
  const r = product && product.aggregateRating;
  if (!r) return null;
  const note = parseFloat(String(r.ratingValue).replace(',', '.'));
  const avis = parseInt(r.reviewCount ?? r.ratingCount, 10);
  return Number.isFinite(note) ? { note: Math.round(note * 10) / 10, avis: Number.isFinite(avis) ? avis : null } : null;
}

function offersOf(product) {
  const o = product && product.offers;
  if (!o) return null;
  return { total: Number(o.offerCount ?? 0), min: o.lowPrice != null ? Number(o.lowPrice) : null, max: o.highPrice != null ? Number(o.highPrice) : null };
}

if (typeof module !== 'undefined' && module.exports) module.exports = { extractJsonLd, findProduct, ratingOf, offersOf };


// ---- lib/okkazeo.js
const PRICE_RE = /^(\d+)\s*€\s*(\d{2})\b/;

function htmlToLines(html) {
  return String(html || '')
    .replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(div|p|li|h\d|tr|section|article|header|footer)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#0?39;|&rsquo;|&apos;/g, "'").replace(/&euro;/g, '€')
    .split('\n').map(s => s.replace(/\s+/g, ' ').trim()).filter(Boolean);
}

function parseAnnonces(lines) {
  const out = [];
  for (let i = 0; i < lines.length; i++) {
    const p = lines[i].match(PRICE_RE);
    if (!p) continue;
    let j = i + 1;
    while (j < lines.length && j < i + 12 && !PRICE_RE.test(lines[j])) j++;
    const win = lines.slice(i + 1, j);
    const v = win.findIndex(l => /^Vendu par\b/i.test(l));
    if (v === -1) continue;
    const loc = win.map(l => l.match(/^(.+?) \((\d{4,5})\)$/)).find(Boolean); // 4 chiffres = annonces étrangères (ex. Belgique)
    const d = win.map(l => l.match(/^(\d{2})\/(\d{2})\/(\d{4})$/)).find(Boolean);
    const head = lines[i - 1] || '';
    const paren = (head.match(/\(([^()]+)\)\s*$/) || [])[1];
    const etat = /^Jeu neuf\b/i.test(head) ? 'neuf' : paren ? paren.replace(/^état\s+/i, '') : head;
    out.push({
      prix: Number(p[1]) + Number(p[2]) / 100,
      etat: etat.trim(),
      ville: loc ? loc[1].trim() : null,
      cp: loc ? loc[2] : null,
      date: d ? `${d[3]}-${d[2]}-${d[1]}` : null,
      bonneAffaire: /bonne affaire/i.test(lines[i]) || win.slice(0, v).some(l => /bonne affaire/i.test(l)),
      extensions: /extension/i.test(head),
      envoi: win.some(l => /Envoi en France/i.test(l)),
    });
  }
  return out;
}

function filterParis(annonces, cps) {
  const set = new Set(cps);
  return (annonces || []).filter(a => a.cp && set.has(a.cp)).sort((a, b) => a.prix - b.prix);
}

if (typeof module !== 'undefined' && module.exports) module.exports = { htmlToLines, parseAnnonces, filterParis };


// ---- lib/sites.js
// Parseurs des pages de recherche (structure observée le 2026-10-13, voir docs/sources.md).
// Pas de `URL` dans le bac à sable des nodes Code n8n (vérifié le 2026-10-13) : résolution à la main.
function absUrl(base, href) {
  const h = String(href || '').trim();
  if (!h) return null;
  if (/^https?:\/\//i.test(h)) return h;
  if (h.startsWith('//')) return 'https:' + h;
  const origin = (String(base).match(/^https?:\/\/[^/]+/i) || [])[0];
  if (!origin) return null;
  return origin + (h.startsWith('/') ? h : '/' + h);
}

function clean(s) {
  return String(s || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#0?39;|&#x27;|&apos;/g, "'").replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ').trim();
}

// Philibert : une carte = <div class="product-card … " data-pid="…">, titre dans a.product-card__title,
// langue dans span.product-card__feature, note « x/5 » avant le titre si le produit a des avis.
function parsePhilibertSearch(html) {
  const out = [];
  for (const card of String(html || '').split(/(?=<div\s+class="product-card\s[^"]*"\s+data-pid=)/).slice(1)) {
    const a = card.match(/<a class="h6 mb-0 product-card__title[^"]*" href="([^"]+)">([^<]+)<\/a>/);
    if (!a) continue;
    const features = [...card.matchAll(/<span class="product-card__feature">([^<]*)<\/span>/g)].map(m => clean(m[1]));
    const lang = features.includes('Français') ? 'fr' : features.includes('Anglais') ? 'en' : undefined;
    const n = clean(card.slice(0, a.index)).match(/(\d(?:[.,]\d)?)\/5/);
    out.push({
      title: clean(a[2]),
      url: absUrl('https://www.philibertnet.com/', a[1]),
      lang,
      note: n ? parseFloat(n[1].replace(',', '.')) : null,
    });
  }
  return out;
}

// Esprit Jeu : <h3 class="bp_designation"><a href="…"> Titre </a></h3>
function parseEspritJeuSearch(html) {
  return [...String(html || '').matchAll(/<h3 class="bp_designation">\s*<a href="([^"]+)">\s*([^<]*?)\s*<\/a>/g)]
    .map(m => ({ title: clean(m[2]), url: absUrl('https://www.espritjeu.com/', m[1]) }))
    .filter(c => c.title && c.url);
}

// Okkazeo : un résultat = <article class="… jeu …"> avec <h4 class="titre"><a href="/jeux/<id>/<slug>">Titre</a></h4>
// et <b>N annonces</b> (nombre d'annonces de cette édition ; null si absent).
function parseOkkazeoSearch(html) {
  const out = [];
  for (const art of String(html || '').split(/(?=<article class="grid-x box_article jeu)/).slice(1)) {
    const a = art.match(/<h4 class="titre"><a href="(\/jeux\/\d+\/[^"]*)"[^>]*>([^<]*)<\/a>/);
    if (!a) continue;
    const n = art.match(/<b>\s*(\d+)\s+annonces?\s*<\/b>/);
    const c = { title: clean(a[2]), url: absUrl('https://www.okkazeo.com/', a[1]), annonces: n ? Number(n[1]) : null };
    if (c.title && c.url) out.push(c);
  }
  return out;
}

